\textbf{14.} $N(50) = 10$, $\Nsm(50) = 9.423$, wobble $+0.577$. $N(100) = 29$, $\Nsm(100) = 29.002$, wobble $-0.002$. Code:
\begin{pycode}
import numpy as np
import qmnt
t = qmnt.zeros(40)
for T in (50.0, 100.0):
    N = np.sum(t <= T)
    print(T, N, qmnt.Nsm(T), N - qmnt.Nsm(T))
\end{pycode}

